import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    a = [int(x) for x in input_data[1:n+1]]

    dist = [-1] * n
    dist[0] = 0
    queue = deque([0])

    while queue:
        u = queue.popleft()

        neighbors = []

        if u > 0:
            neighbors.append(u - 1)
        if u < n - 1:
            neighbors.append(u + 1)

        v_shortcut = a[u] - 1
        if v_shortcut != u:
            neighbors.append(v_shortcut)

        for v in neighbors:
            if dist[v] == -1:
                dist[v] = dist[u] + 1
                queue.append(v)

    print(' '.join(map(str, dist)))

if __name__ == '__main__':
    solve()
